// Staged runner: typed handoffs, logged, independently re-runnable
async function runPipeline(callModel, ticket, policyText) {
  const log = [];
  const s1 = await callModel("extract", { ticket });          // -> {order_id, issue, dates}
  log.push(["extract", s1]);
  const s2 = await callModel("decide", { facts: s1, policyText }); // -> {approved, reason}
  log.push(["decide", s2]);
  const s3 = await callModel("draft", { decision: s2 });       // -> reply text
  log.push(["draft", s3]);
  const s4 = await callModel("verify", { reply: s3 });        // -> {pass, fixes}
  log.push(["verify", s4]);
  return { final: s4.pass ? s3 : { needsFix: s4.fixes }, log };
}
// Swap any stage's prompt without touching others; replay from any log entry.

// Checklist verifier (deterministic code beats model judgment for mechanics)
function verifyReply(reply, decision) {
  const fixes = [];
  if (reply.split(/\s+/).length > 60) fixes.push("over 60 words");
  if (/refund|timeline|guarantee/i.test(reply) && !decision.approved) fixes.push("promises without approval");
  if (!reply.toLowerCase().includes(decision.key || "label")) fixes.push("missing return-label offer");
  return { pass: fixes.length === 0, fixes };
}
// Mechanics (length, phrases) in code; judgment (tone, correctness) to the model.

